  '    IO.puts(inspect(Enum.frequencies(["", "", "a", "abcdefgh", "abcdefghi", "abcdefgh", "abcdefghijklmnopq", "é", "é"])))\n'
  '    IO.puts(inspect(Enum.group_by(1..20, fn x -> rem(x, 3) end)))\n'
  '    IO.puts(inspect(Enum.frequencies(%{1 => 2, 3 => 4})))\n'
  '  end\n'
  'end\n',
